const CZ=-45;
function P(R){const t=Math.min(1,Math.max(0,(R-24)/126));return 40.6*(1-t*t*(3-2*t));}
const rings=[[132,60],[112,62],[92,64],[72,66],[54,70]];
const S=[[0,-5,0,118,3.2],[32.9,0.3,75.3,58.6,2.2],[-32.9,0.3,-75.3,58.6,2.8],[-135,122,135,122,3.5],[-100.7,59.3,-100.7,122,3],[100.7,59.3,100.7,122,3],[0,-5,0,-30,3]];
const zz=[[-100.7,59.3],[-130,-22.1],[-90.4,30.8],[-103.4,-34.1],[-72.8,7.9],[-75.8,-39.7],[-52.6,-12.1],[-51.4,-28.3]];
for(let i=0;i<zz.length-1;i++){S.push([zz[i][0],zz[i][1],zz[i+1][0],zz[i+1][1],3]);S.push([-zz[i][0],zz[i][1],-zz[i+1][0],zz[i+1][1],3]);}
const BB=S.map(s=>[Math.min(s[0],s[2])-12,Math.max(s[0],s[2])+12,Math.min(s[1],s[3])-12,Math.max(s[1],s[3])+12]);
const PL=[[0,110,15,0],[0,47,12,17.9],[24.6,22.7,11,27.4],[0,-5,10,38.75],[0,-45,26,40.6]];
let gw=0;
function sm(a,b,x){const t=Math.min(1,Math.max(0,(x-a)/(b-a)));return t*t*(3-2*t);}
function H(x,z){
 const R=Math.hypot(x,z-CZ);let h=P(R);
 let best=1e9,by=0;
 if(R<150){const th=Math.abs(Math.atan2(x,z-CZ))*57.2958;
  for(let i=0;i<5;i++){const d=Math.abs(R-rings[i][0]);if(d<12&&th<=rings[i][1]+2){const e=d-3;if(e<best){best=e;by=P(rings[i][0]);}}}}
 for(let i=0;i<S.length;i++){const s=S[i],b=BB[i];
  if(x<b[0]||x>b[1]||z<b[2]||z>b[3])continue;
  const dx=s[2]-s[0],dz=s[3]-s[1];let t=((x-s[0])*dx+(z-s[1])*dz)/(dx*dx+dz*dz);t=Math.min(1,Math.max(0,t));
  const px=s[0]+dx*t,pz=s[1]+dz*t;const e=Math.hypot(x-px,z-pz)-s[4];
  if(e<best){best=e;by=P(Math.hypot(px,pz-CZ));}}
 for(let i=0;i<PL.length;i++){const p=PL[i];const e=Math.hypot(x-p[0],z-p[1])-p[2];if(e<best){best=e;by=p[3];}}
 const w=1-sm(0.8,7.5,best);
 const nz=0.6*Math.sin(x*0.07+z*0.05)+0.4*Math.sin(x*0.13-z*0.11+2);
 h=h+0.45*nz*(1-w)*(R>135?1:0.5);
 h=h*(1-w)+by*w;
 if(z>175)h+=0.03*(z-175);
 const zc=152+6*Math.sin(x/45);const dd=Math.abs(z-zc);
 if(dd<14){const u=sm(0,1,(14-dd)/3);h=h*(1-u)-3.2*u;}
 gw=w;
 return h;
}
const N=params.res;const cell=420/(N-1);
const W=new Float32Array(N*N);
const m=api.heightfield(N,N,420,420,(x,z)=>{const h=H(x,z);const i=Math.round((x+210)/cell),j=Math.round((z+210)/cell);W[j*N+i]=gw;return h;});
m.vertexColor((x,y,z)=>{
 const i=Math.round((x+210)/cell),j=Math.round((z+210)/cell);const w=W[j*N+i]||0;
 const zc=152+6*Math.sin(x/45);const dd=Math.abs(z-zc);
 if(dd<14.5)return y<-1?'#4d5148':'#9c9482';
 if(dd<17&&y<0.6)return '#b0a68c';
 if(w>0.5)return '#8a8378';
 const n=0.5+0.5*Math.sin(x*0.21)*Math.cos(z*0.17);
 return api.mix(api.mix('#8a8a54','#6d7c46',n),'#9c8b5c',Math.min(1,w*0.8+0.2*(0.5+0.5*Math.sin(x*0.05+z*0.04))));
});
api.add(m,{color:'#ffffff',roughness:0.95});
api.add(api.box(0.02,0.02,0.02).translate(0,-5,0),{color:'#000000'});
return api.build();

lisbon-houses.source:
const CZ=-45;
function P(R){const t=Math.min(1,Math.max(0,(R-24)/126));return 40.6*(1-t*t*(3-2*t));}
const rings=[[132,60],[112,62],[92,64],[72,66],[54,70]];
const S=[[0,-5,0,118,3.2],[32.9,0.3,75.3,58.6,2.2],[-32.9,0.3,-75.3,58.6,2.8],[-135,122,135,122,3.5],[-100.7,59.3,-100.7,122,3],[100.7,59.3,100.7,122,3],[0,-5,0,-30,3]];
const zz=[[-100.7,59.3],[-130,-22.1],[-90.4,30.8],[-103.4,-34.1],[-72.8,7.9],[-75.8,-39.7],[-52.6,-12.1],[-51.4,-28.3]];
for(let i=0;i<zz.length-1;i++){S.push([zz[i][0],zz[i][1],zz[i+1][0],zz[i+1][1],3]);S.push([-zz[i][0],zz[i][1],-zz[i+1][0],zz[i+1][1],3]);}
const PL=[[0,110,15],[0,47,12],[24.6,22.7,11],[0,-5,10],[0,-45,26]];
function roadE(x,z,sr,ss){
 let best=1e9;const R=Math.hypot(x,z-CZ);
 if(R<150){const th=Math.abs(Math.atan2(x,z-CZ))*57.2958;
  for(let i=0;i<5;i++){if(i===sr)continue;const d=Math.abs(R-rings[i][0]);if(th<=rings[i][1]+3){const e=d-3;if(e<best)best=e;}}}
 for(let i=0;i<S.length;i++){if(i===ss)continue;const s=S[i];
  const dx=s[2]-s[0],dz=s[3]-s[1];let t=((x-s[0])*dx+(z-s[1])*dz)/(dx*dx+dz*dz);t=Math.min(1,Math.max(0,t));
  const e=Math.hypot(x-s[0]-dx*t,z-s[1]-dz*t)-s[4];if(e<best)best=e;}
 for(let i=0;i<PL.length;i++){const e=Math.hypot(x-PL[i][0],z-PL[i][1])-PL[i][2];if(e<best)best=e;}
 return best;}
const MV={color:'#ffffff',roughness:0.88};
const MG={color:'#26323b',roughness:0.08,metalness:0.7};
const MI={color:'#1b1d20',roughness:0.45,metalness:0.8};
const wallP=['#ecd3a8','#f2dc8e','#eaaa9e','#a9cbc0','#c3d6e6','#e8b6c2','#f4e8d2','#dba66c','#b9d4a6','#cdbcdc','#f0c49a','#9fc2c9'];
const roofP=['#b4532c','#a64a28','#c0643a','#9c4a2e'];
const azP=[['#f3efe4','#1f4e9a'],['#f1e6c4','#c99a2e'],['#e9f0e0','#2f7a5a'],['#efe9dc','#2c6f9a'],['#f2ebe0','#b0503a']];
const doorP=['#4a2e1e','#2f4a3a','#6b2a2a','#23364f','#3d3d3d'];
const rnd=()=>api.rng();
const pick=a=>a[Math.floor(rnd()*a.length)];
const vb=(w,h,d,c)=>api.box(w,h,d).vertexColor(()=>c);
function house(cx,cz,y0,n,w,d,fh,f,pf){
 const psi=Math.atan2(n[0],n[1])*57.2958;
 const put=(m,mat)=>{m.rotate(0,psi,0).translate(cx,y0,cz);api.add(m,mat);};
 const wc=pick(wallP),hb=f*3.1,rh=1.1+d*0.16;
 put(vb(w,fh,d,'#85817a').translate(0,-fh/2,d/2),MV);
 put(vb(w,hb,d,wc).translate(0,hb/2,d/2),MV);
 if(rnd()<pf){const az=pick(azP);const cs=0.38;
  const pl=api.plane(w,hb,Math.max(2,Math.round(w/cs)),Math.max(2,Math.round(hb/cs))).vertexColor((x,y,z)=>((Math.round((x+w/2)/cs)+Math.round((z+hb/2)/cs))&1)?az[1]:az[0]);
  put(pl.rotate(-90,0,0).translate(0,hb/2,-0.012),MV);}
 const rf=api.extrude([[-(d/2+0.35),0],[d/2+0.35,0],[0,rh]],w+0.4).vertexColor(()=>pick(roofP)).rotate(0,-90,0);
 const b=rf.bounds();rf.translate(-(b.min[0]+b.max[0])/2,hb-b.min[1],d/2-(b.min[2]+b.max[2])/2);put(rf,MV);
 put(vb(w+0.15,0.3,0.4,'#f4ede0').translate(0,hb+0.1,-0.05),MV);
 if(rnd()<0.5)put(vb(0.55,1.4,0.55,'#d8ccb6').translate((rnd()-0.5)*w*0.6,hb+rh*0.6,d*0.7),MV);
 const nw=Math.max(2,Math.round(w/2.7));const trim=rnd()<0.5?'#f6f0e4':'#e9d9b4';
 for(let k=0;k<nw;k++){const x=-w/2+(k+0.5)*w/nw;
  for(let i=0;i<f;i++){
   if(i===0){ if(k===0){put(vb(1.05,2.3,0.14,pick(doorP)).translate(x,1.15,-0.04),MV);continue;}
     put(vb(1.15,1.5,0.07,trim).translate(x,1.5,-0.02),MV);put(api.box(0.9,1.25,0.05).translate(x,1.5,-0.06),MG);continue;}
   const yc=i*3.1+1.7;
   put(vb(1.15,1.8,0.07,trim).translate(x,yc,-0.02),MV);put(api.box(0.9,1.55,0.05).translate(x,yc,-0.06),MG);
   if(rnd()<0.55){const yb=i*3.1+0.7;
    put(api.box(1.5,0.07,0.62).translate(x,yb,-0.33),MI);
    put(api.box(1.5,0.05,0.05).translate(x,yb+1.0,-0.62),MI);
    put(api.box(1.5,0.04,0.04).translate(x,yb+0.4,-0.62),MI);
    for(let j=-1;j<=1;j++)put(api.box(0.025,0.95,0.025).translate(x+j*0.5,yb+0.5,-0.62),MI);
    put(api.box(0.05,1.0,0.05).translate(x-0.73,yb+0.5,-0.62),MI);put(api.box(0.05,1.0,0.05).translate(x+0.73,yb+0.5,-0.62),MI);}
  }}
 const hh=fh+hb+rh;const ox=Math.sin(psi/57.2958)*d/2,oz=Math.cos(psi/57.2958)*d/2;
 api.collider({kind:'box',halfExtents:[w/2,hh/2,d/2],offset:[cx+ox,y0+(hb+rh-fh)/2,cz+oz],rotation:[0,psi,0]});
}
const DEF=[
 {t:'r',i:0,sd:[1,-1],f:5,fh:4},{t:'r',i:1,sd:[1,-1],f:4,fh:4},{t:'r',i:2,sd:[1,-1],f:4,fh:4},{t:'r',i:3,sd:[1,-1],f:3,fh:4},{t:'r',i:4,sd:[1],f:3,fh:4},
 {t:'s',i:0,sd:[1,-1],f:4,fh:7},{t:'s',i:1,sd:[1,-1],f:3,fh:7},{t:'s',i:2,sd:[1,-1],f:3,fh:7},{t:'s',i:3,sd:[-1],f:4,fh:3},{t:'s',i:4,sd:[1,-1],f:3,fh:5},{t:'s',i:5,sd:[1,-1],f:3,fh:5},{t:'s',i:3,sd:[1],f:3,fh:3}];
const D=DEF[params.street];
const F=4.2,GAP=0.15;
function nf(base){const r=rnd();return Math.max(2,Math.min(5,Math.round(base-1+r*3)));}
const WM=4.8,WR=3.2;
if(D.t==='r'){const rr=rings[D.i];const Rc=rr[0],Th=rr[1]*Math.PI/180;
 for(const sg of D.sd){const Rf=Rc+sg*F;let s=-Th;
  while(s<Th-0.05){const w=WM+rnd()*WR,d=5.3;const dt=w/Rf;
   if(s+dt>Th)break;const th=s+dt/2;
   const cx=Rf*Math.sin(th),cz=CZ+Rf*Math.cos(th);const n=[sg*Math.sin(th),sg*Math.cos(th)];
   const hx=cx+n[0]*d/2,hz=cz+n[1]*d/2;
   if(roadE(hx,hz,D.i,-1)>2.2 && roadE(cx,cz,D.i,-1)>0.3){house(cx,cz,P(Rc)+0.12,n,w,d,D.fh,nf(D.f),0.4);}
   s+=dt+GAP/Rf;}}
}else{const sg0=S[D.i];const ax=sg0[0],az=sg0[1],bx=sg0[2],bz=sg0[3];const L=Math.hypot(bx-ax,bz-az);const ux=(bx-ax)/L,uz=(bz-az)/L;
 for(const sg of D.sd){const nx=sg*(-uz),nz=sg*ux;let s=3;
  while(s<L-3){const w=WM+rnd()*WR,d=5.3;
   const mx=ax+ux*(s+w/2),mz=az+uz*(s+w/2);const cx=mx+nx*(sg0[4]+1.4),cz=mz+nz*(sg0[4]+1.4);
   const e1=P(Math.hypot(ax+ux*s,az+uz*s-CZ)),e2=P(Math.hypot(ax+ux*(s+w),az+uz*(s+w)-CZ));
   const hx=cx+nx*d/2,hz=cz+nz*d/2;
   const bridge=(D.i===3&&Math.abs(cx)<11);
   if(!bridge&&roadE(hx,hz,-1,D.i)>2.2 && roadE(cx,cz,-1,D.i)>0.3){house(cx,cz,Math.min(e1,e2)+0.12,[nx,nz],w,d,D.fh+Math.abs(e1-e2),nf(D.f),0.4);}
   s+=w+GAP;}}
}
api.add(api.box(0.02,0.02,0.02).translate(-215,-5,-215),{color:'#000'});
api.add(api.box(0.02,0.02,0.02).translate(215,-5,215),{color:'#000'});
return api.build();

lisbon-roads.source:
const CZ=-45;
function P(R){const t=Math.min(1,Math.max(0,(R-24)/126));return 40.6*(1-t*t*(3-2*t));}
const rings=[[132,60],[112,62],[92,64],[72,66],[54,70]];
const S=[[0,-5,0,118,3.2],[32.9,0.3,75.3,58.6,2.2],[-32.9,0.3,-75.3,58.6,2.8],[-135,122,135,122,3.5],[-100.7,59.3,-100.7,122,3],[100.7,59.3,100.7,122,3],[0,-5,0,-30,3]];
const zz=[[-100.7,59.3],[-130,-22.1],[-90.4,30.8],[-103.4,-34.1],[-72.8,7.9],[-75.8,-39.7],[-52.6,-12.1],[-51.4,-28.3]];
const ZW=[],ZE=[];
for(let i=0;i<zz.length-1;i++){ZW.push([zz[i][0],zz[i][1],zz[i+1][0],zz[i+1][1],3]);ZE.push([-zz[i][0],zz[i][1],-zz[i+1][0],zz[i+1][1],3]);}
const MV={color:'#ffffff',roughness:0.93};
const MI={color:'#222428',roughness:0.45,metalness:0.8};
const ML={color:'#ffe0a0',emissive:'#ffcf80',emissiveIntensity:2.2,roughness:0.4};
const MR={color:'#5a5d62',roughness:0.35,metalness:0.9};
let cnt=0;
const cobA=['#6b6862','#76726b','#625f5b','#7d7870'],pavA=['#d4cdbd','#ece6d8','#3b3a3a'];
// segment from a to b (points on ground), width hw: road + pavements
function strip(ax,az,bx,bz,w,off,col,yo,th){
 const ya=P(Math.hypot(ax,az-CZ)),yb=P(Math.hypot(bx,bz-CZ));
 const dx=bx-ax,dz=bz-az,len=Math.hypot(dx,dz);if(len<0.05)return;
 const nx=-dz/len,nz=dx/len;
 const m=api.box(w,th,len+0.15).vertexColor(()=>col);
 m.rotate(-Math.atan2(yb-ya,len)*57.2958,0,0).rotate(0,Math.atan2(dx,dz)*57.2958,0).translate((ax+bx)/2+nx*off,(ya+yb)/2+yo,(az+bz)/2+nz*off);
 api.add(m,MV);}
function road(ax,az,bx,bz,hw,pav){
 strip(ax,az,bx,bz,hw*2,0,cobA[(cnt++)&3],0.05,0.1);
 if(pav){strip(ax,az,bx,bz,1.5,hw+0.75,pavA[cnt%3===0?2:cnt&1],0.1,0.16);strip(ax,az,bx,bz,1.5,-(hw+0.75),pavA[cnt%3===1?2:(cnt+1)&1],0.1,0.16);}}
function rail(ax,az,bx,bz){strip(ax,az,bx,bz,0.07,0.72,'#555',0.17,0.08);strip(ax,az,bx,bz,0.07,-0.72,'#555',0.17,0.08);}
function lamp(x,z,ny){const y=P(Math.hypot(x,z-CZ));
 api.add(api.cylinder(0.07,0.1,3.8,6).translate(x,y+1.9+0.15,z),MI);
 api.add(api.box(0.3,0.4,0.3).translate(x,y+4.1,z),ML);}
function lampsAlong(ax,az,bx,bz,hw,every,side){const L=Math.hypot(bx-ax,bz-az),ux=(bx-ax)/L,uz=(bz-az)/L;
 for(let s=every/2;s<L;s+=every)lamp(ax+ux*s-uz*side*(hw+1.6),az+uz*s+ux*side*(hw+1.6));}
function polyRoad(pts,hw,pav,rails,lamps){for(let i=0;i<pts.length-1;i++){}}
function seg(s,pav,rails,lampEvery){const L=Math.hypot(s[2]-s[0],s[3]-s[1]);const n=Math.max(1,Math.ceil(L/3.6));
 for(let i=0;i<n;i++){const a=i/n,b=(i+1)/n;const ax=s[0]+(s[2]-s[0])*a,az=s[1]+(s[3]-s[1])*a,bx=s[0]+(s[2]-s[0])*b,bz=s[1]+(s[3]-s[1])*b;
  road(ax,az,bx,bz,s[4],pav);if(rails)rail(ax,az,bx,bz);}
 if(lampEvery)lampsAlong(s[0],s[1],s[2],s[3],s[4],lampEvery,1);}
if(params.part===0){
 for(let k=0;k<5;k++){const R=rings[k][0],Th=rings[k][1];const st=2.5;
  for(let a=-Th;a<Th;a+=st){const t1=a*Math.PI/180,t2=Math.min(Th,a+st)*Math.PI/180;
   road(R*Math.sin(t1),CZ+R*Math.cos(t1),R*Math.sin(t2),CZ+R*Math.cos(t2),3,true);}
  const L=R*Th*2*Math.PI/180;
  for(let s=10;s<L;s+=24){const t=(-Th+ s/R*57.2958)*Math.PI/180;const r2=R-4.6;lamp(r2*Math.sin(t),CZ+r2*Math.cos(t));}}
 seg(S[0],true,true,22);seg(S[2],true,false,20);seg(S[3],true,false,22);seg(S[4],true,false,0);seg(S[5],true,false,0);seg(S[6],true,false,0);
 // plazas
 const PLZ=[[0,110,15,0],[0,47,12,17.9],[24.6,22.7,11,27.4],[0,-5,10,38.75]];
 for(const p of PLZ){const r=p[2];const m=api.cylinder(r-0.2,r-0.2,0.14,28).vertexColor(()=>'#d9d2c2');api.add(m.translate(p[0],p[3]+0.08,p[1]),MV);
  for(let k=0;k<6;k++){const a=k*1.047;lamp(p[0]+Math.sin(a)*(r-1),p[1]+Math.cos(a)*(r-1));}}
}else{
 for(const s of ZW)seg(s,true,false,26);
 for(const s of ZE)seg(s,true,true,26);
 seg(S[1],false,false,0);
 // stairs on the escadinhas
 const s=S[1];const L=Math.hypot(s[2]-s[0],s[3]-s[1]),ux=(s[2]-s[0])/L,uz=(s[3]-s[1])/L;
 for(let d=1;d<L-1;d+=0.75){const x=s[0]+ux*d,z=s[1]+uz*d;const y=P(Math.hypot(x,z-CZ));
  const m=api.box(4.2,0.18,0.55).vertexColor(()=>((Math.round(d/0.75)&1)?'#b7b0a3':'#a39c90')).rotate(0,Math.atan2(ux,uz)*57.2958,0).translate(x,y+0.09,z);api.add(m,MV);}
 for(const sd of [-1,1]){const m=api.box(0.12,0.9,L).vertexColor(()=>'#2a2a2a').translate(0,0,0);
  m.rotate(-Math.atan2(P(Math.hypot(s[2],s[3]-CZ))-P(Math.hypot(s[0],s[1]-CZ)),L)*57.2958,0,0).rotate(0,Math.atan2(ux,uz)*57.2958,0)
   .translate((s[0]+s[2])/2-uz*sd*2.3,(P(Math.hypot(s[0],s[1]-CZ))+P(Math.hypot(s[2],s[3]-CZ)))/2+0.9,(s[1]+s[3])/2+ux*sd*2.3);api.add(m,MI);}
}
api.add(api.box(0.02,0.02,0.02).translate(-215,-5,-215),{color:'#000'});
api.add(api.box(0.02,0.02,0.02).translate(215,-5,215),{color:'#000'});
api.collider({kind:'box',halfExtents:[0.01,0.01,0.01],offset:[0,-5,0]});
return api.build();

red-suspension-bridge.source:
const red='#b82a22',steel='#8c9096';
const MR={color:red,roughness:0.5,metalness:0.55};
const MD={color:'#47464a',roughness:0.9};
const MS={color:'#bdb6a8',roughness:0.9};
const MG={color:steel,roughness:0.4,metalness:0.8};
const DY=1.2;
// deck
api.add(api.box(9,0.4,34).translate(0,DY-0.2,0),MD);
api.collider({kind:'box',halfExtents:[4.5,0.2,17],offset:[0,DY-0.2,0]});
for(const sd of [-1,1]){
 api.add(api.box(1.2,0.3,34).translate(sd*3.9,DY+0.15,0),MS);
 api.add(api.box(0.25,0.9,34).translate(sd*4.45,DY+0.45,0),MG);
 api.add(api.box(0.25,0.5,34).translate(sd*4.45,DY-0.4,0),MR);
}
const ang=Math.atan2(DY,8.2)*57.2958;
for(const sg of [-1,1]){
