hero-fountain.source:
const s = params.width / 3.4;
const stoneMat = { preset: 'stone', roughness: 0.92, flatShading: true };
const waterMat = { preset: 'water', color: params.waterColor, opacity: 0.7, roughness: 0.05, emissive: params.waterColor, emissiveIntensity: 0.5 };
const sheetMat = { preset: 'water', color: '#bfe6ff', opacity: 0.45, roughness: 0.05, emissive: '#7fc8ff', emissiveIntensity: 0.8 };
function stone(m, dark) {
  m.vertexColor((x, y, z) => {
    const n = api.noise3(x * 3, y * 3, z * 3);
    let c = api.mix(params.stoneColor, '#8a6c4a', 0.2 + 0.2 * n + (dark || 0));
    if (y < 0.3) c = api.mix(c, '#5f6b45', 0.2);
    return c;
  });
  api.add(m.scale(s), stoneMat);
}
function water(m) { api.add(m.scale(s), waterMat); }
function sheet(m) { api.add(m.scale(s), sheetMat); }
// basin
stone(api.lathe([[0,0],[1.45,0],[1.55,0.08],[1.6,0.15],[1.6,0.68],[1.68,0.7],[1.72,0.76],[1.72,0.82],[1.55,0.82],[1.5,0.74],[1.45,0.7],[1.45,0.28],[0,0.28]], 8));
stone(api.cylinder(1.5, 1.55, 0.06, 8).translate(0, 0.03, 0), 0.1);
water(api.cylinder(1.43, 1.43, 0.03, 8).translate(0, 0.62, 0));
if (params.panels) {
  const ap = 1.6 * Math.cos(Math.PI / 8);
  for (let k = 0; k < 8; k++) {
    const a = 22.5 + 45 * k, r = a * Math.PI / 180;
    const px = Math.sin(r) * (ap + 0.015), pz = Math.cos(r) * (ap + 0.015);
    stone(api.box(0.8, 0.38, 0.05).rotate(0, a, 0).translate(px, 0.4, pz), -0.1);
    stone(api.box(0.6, 0.22, 0.06).rotate(0, a, 0).translate(Math.sin(r) * (ap + 0.03), 0.4, Math.cos(r) * (ap + 0.03)), 0.12);
  }
}
// pedestal
stone(api.lathe([[0,0.28],[0.5,0.28],[0.5,0.36],[0.36,0.45],[0.3,0.6],[0.24,0.7],[0.24,1.1],[0.3,1.2],[0.34,1.3],[0,1.3]], 16));
stone(api.cylinder(0.22, 0.22, 0.5, 16).translate(0, 0.9, 0));
for (let i = 0; i < 12; i++) {
  const a = i / 12 * Math.PI * 2;
  stone(api.cylinder(0.03, 0.03, 0.5, 6).translate(Math.sin(a) * 0.235, 0.9, Math.cos(a) * 0.235), 0.12);
}
// bowl 1 scalloped
const b1 = api.lathe([[0,1.25],[0.2,1.25],[0.3,1.35],[0.95,1.6],[1.0,1.66],[1.0,1.72],[0.92,1.72],[0.85,1.6],[0.2,1.45],[0,1.45]], 24);
b1.displace((x, y, z) => y > 1.4 ? 0.03 * Math.cos(Math.atan2(x, z) * 12) : 0);
stone(b1);
water(api.cylinder(0.85, 0.85, 0.03, 24).translate(0, 1.62, 0));
stone(api.cylinder(0.14, 0.16, 0.6, 12).translate(0, 1.75, 0));
// bowl 2
const b2 = api.lathe([[0,1.95],[0.12,1.95],[0.2,2.02],[0.57,2.2],[0.62,2.25],[0.62,2.3],[0.55,2.3],[0.5,2.2],[0.12,2.1],[0,2.1]], 20);
b2.displace((x, y, z) => y > 2.1 ? 0.025 * Math.cos(Math.atan2(x, z) * 10) : 0);
stone(b2);
water(api.cylinder(0.48, 0.48, 0.03, 20).translate(0, 2.2, 0));
// finial
stone(api.cylinder(0.06, 0.09, 0.5, 10).translate(0, 2.35, 0));
stone(api.cylinder(0.12, 0.1, 0.05, 10).translate(0, 2.58, 0));
const pc = api.sphere(0.17, 2).scale(1, 1.4, 1).translate(0, 2.8, 0);
pc.displace((x, y, z) => 0.025 * Math.sin(y * 40 + Math.atan2(x, z) * 6));
stone(pc, 0.05);
stone(api.cone(0.05, 0.12, 8).translate(0, 3.0, 0));
// falling sheets
for (let i = 0; i < 8; i++) {
  const a = i * 45 + 22.5, r = a * Math.PI / 180;
  sheet(api.box(0.1, 0.4, 0.012).rotate(0, a, 0).translate(Math.sin(r) * 0.63, 1.95, Math.cos(r) * 0.63));
  sheet(api.box(0.12, 1.0, 0.012).rotate(0, a, 0).translate(Math.sin(r) * 1.0, 1.12, Math.cos(r) * 1.0));
}
sheet(api.cylinder(0.025, 0.025, 0.2, 6).translate(0, 3.05, 0));
// colliders
api.collider({ kind: 'cylinder', radius: 1.7 * s, halfHeight: 0.41 * s, offset: [0, 0.41 * s, 0] });
api.collider({ kind: 'cylinder', radius: 0.3 * s, halfHeight: 0.8 * s, offset: [0, 1.0 * s, 0] });
api.collider({ kind: 'cylinder', radius: 1.0 * s, halfHeight: 0.25 * s, offset: [0, 1.5 * s, 0] });
api.collider({ kind: 'cylinder', radius: 0.6 * s, halfHeight: 0.2 * s, offset: [0, 2.15 * s, 0] });
api.collider({ kind: 'cylinder', radius: 0.1 * s, halfHeight: 0.4 * s, offset: [0, 2.6 * s, 0] });
return api.build();

beach-umbrella.source:
const main = params.color;
const stripe = params.stripeColor;
const tilt = params.tilt;
const ang = tilt * Math.PI / 180;
const cs = Math.cos(ang);
const sn = Math.sin(ang);
const poleH = 2.35;
const poleR = 0.027;
const canopyR = 1.18;
const hubY = 2.16;
const tx = -sn * poleH * 0.5;
const ty = cs * poleH * 0.5;
const point = (x, y, z) => [x * cs - y * sn, x * sn + y * cs, z];
const fabric = { preset: 'fabric', roughness: 0.82, flatShading: true };
const wood = { preset: 'wood', color: '#9a673d', roughness: 0.62 };
const metal = { preset: 'metal', color: '#d8d2c3', metalness: 0.65, roughness: 0.32 };
const sand = { preset: 'sand', color: '#d9bd83', roughness: 1, flatShading: true };
api.add(api.icosphereRock(0.34, 0.32).scale(1.55, 0.28, 1.35).translate(0, 0.06, 0), sand);
api.add(api.cylinder(poleR, poleR * 1.08, poleH, 12).rotate(0, 0, tilt).translate(tx, ty, 0), wood);
const capProfile = [[0, hubY + 0.34], [canopyR * 0.2, hubY + 0.3], [canopyR * 0.48, hubY + 0.19], [canopyR * 0.76, hubY + 0.03], [canopyR, hubY - 0.16], [canopyR * 0.98, hubY - 0.22], [canopyR * 0.74, hubY - 0.04], [canopyR * 0.47, hubY + 0.12], [canopyR * 0.19, hubY + 0.24], [0, hubY + 0.28]];
const canopy = api.lathe(capProfile, 32).rotate(0, 0, tilt);
canopy.vertexColor((x, y, z) => {
  let a = Math.atan2(z, x);
  if (a < 0) a += Math.PI * 2;
  return Math.floor(a / (Math.PI / 4)) % 2 === 0 ? main : stripe;
});
api.add(canopy, fabric);
const top = point(0, hubY + 0.35, 0);
api.add(api.sphere(0.065, 1).translate(top[0], top[1], top[2]), metal);
const hub = point(0, hubY - 0.03, 0);
api.add(api.cylinder(0.065, 0.075, 0.12, 12).rotate(0, 0, tilt).translate(hub[0], hub[1], hub[2]), metal);
for (let i = 0; i < 8; i++) {
  const a = i * Math.PI / 4;
  const inner = point(Math.cos(a) * 0.07, hubY - 0.02, Math.sin(a) * 0.07);
  const edge = point(Math.cos(a) * canopyR * 0.94, hubY - 0.17, Math.sin(a) * canopyR * 0.94);
